package com.hbm.world.structure.generated;
import com.hbm.multiblock.DummyableBlock;
import com.hbm.world.structure.NaturalStructures;
import com.hbm.world.structure.generated.compat.World;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.ChunkGenerator;
import net.minecraft.world.level.chunk.ProtoChunk;
import net.minecraft.world.level.chunk.ImposterProtoChunk;
import net.minecraft.world.level.levelgen.structure.*;
import net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext;
/** Native persistent chunk-sized pieces of the complete executed source plan; repeated source writes retain their order. */
public final class GeneratedPlanPiece extends StructurePiece {
 private final List<World.PlannedWrite> writes;private final Map<BlockPos,CompoundTag> tiles;private final List<World.PlannedAttachment> attachments;private final GeneratedDependencies dependencies;
 public static List<GeneratedPlanPiece> split(World world,GeneratedDependencies dependencies){var groups=new LinkedHashMap<ChunkPos,List<World.PlannedWrite>>();for(var write:world.plannedWrites())groups.computeIfAbsent(new ChunkPos(write.position()),ignored->new ArrayList<>()).add(write);var pieces=new ArrayList<GeneratedPlanPiece>();for(var group:groups.entrySet()){var tiles=new LinkedHashMap<BlockPos,CompoundTag>();for(var entry:world.plannedTiles().entrySet())if(new ChunkPos(entry.getKey()).equals(group.getKey()))tiles.put(entry.getKey(),entry.getValue().saveWithId(world.lookup()));var attachments=world.plannedAttachments().stream().filter(value->new ChunkPos(value.position()).equals(group.getKey())).toList();pieces.add(new GeneratedPlanPiece(group.getValue(),tiles,attachments,dependencies));}return pieces;}
 private static BoundingBox box(List<World.PlannedWrite> writes){var first=writes.getFirst().position();var box=new BoundingBox(first);for(var write:writes)box.encapsulate(write.position());return box;}
 private GeneratedPlanPiece(List<World.PlannedWrite> writes,Map<BlockPos,CompoundTag> tiles,List<World.PlannedAttachment> attachments,GeneratedDependencies dependencies){super(GeneratedStructures.PLAN_PIECE.get(),0,box(writes));this.writes=List.copyOf(writes);this.tiles=Map.copyOf(tiles);this.attachments=List.copyOf(attachments);this.dependencies=dependencies;}
 public GeneratedPlanPiece(StructurePieceSerializationContext context,CompoundTag tag){super(GeneratedStructures.PLAN_PIECE.get(),tag);dependencies=GeneratedDependencies.load(tag.getCompound("sourceDependencies"));var palette=new ArrayList<BlockState>();for(var raw:tag.getList("sourcePalette",Tag.TAG_COMPOUND)){var state=(CompoundTag)raw;var id=ResourceLocation.parse(state.getString("Name"));if(!context.registryAccess().registryOrThrow(Registries.BLOCK).containsKey(id))throw new IllegalStateException("Unported real source-plan palette block "+id);palette.add(NbtUtils.readBlockState(context.registryAccess().lookupOrThrow(Registries.BLOCK),state));}long[] positions=tag.getLongArray("sourcePositions");int[] values=tag.getIntArray("sourceValues");if(positions.length!=values.length)throw new IllegalStateException("Corrupt original source plan");var writes=new ArrayList<World.PlannedWrite>();for(int i=0;i<positions.length;i++)writes.add(new World.PlannedWrite(BlockPos.of(positions[i]),palette.get(values[i]>>>8),values[i]&255));this.writes=List.copyOf(writes);var tiles=new LinkedHashMap<BlockPos,CompoundTag>();for(var raw:tag.getList("sourceTiles",Tag.TAG_COMPOUND)){var row=(CompoundTag)raw;tiles.put(BlockPos.of(row.getLong("position")),row.getCompound("data"));}this.tiles=Map.copyOf(tiles);var effects=new ArrayList<World.PlannedAttachment>();for(var raw:tag.getList("sourceAttachments",Tag.TAG_COMPOUND)){var row=(CompoundTag)raw;effects.add(new World.PlannedAttachment(row.getString("kind"),BlockPos.of(row.getLong("position")),row.getCompound("data")));}attachments=List.copyOf(effects);}
 @Override protected void addAdditionalSaveData(StructurePieceSerializationContext context,CompoundTag tag){tag.put("sourceDependencies",dependencies.save());var indices=new IdentityHashMap<BlockState,Integer>();var palette=new ListTag();long[] positions=new long[writes.size()];int[] values=new int[writes.size()];for(int i=0;i<writes.size();i++){var write=writes.get(i);Integer index=indices.get(write.state());if(index==null){index=palette.size();indices.put(write.state(),index);palette.add(NbtUtils.writeBlockState(write.state()));}positions[i]=write.position().asLong();values[i]=(index<<8)|(write.flags()&255);}tag.put("sourcePalette",palette);tag.putLongArray("sourcePositions",positions);tag.putIntArray("sourceValues",values);var be=new ListTag();for(var entry:tiles.entrySet()){var row=new CompoundTag();row.putLong("position",entry.getKey().asLong());row.put("data",entry.getValue());be.add(row);}tag.put("sourceTiles",be);var effects=new ListTag();for(var effect:attachments){var row=new CompoundTag();row.putString("kind",effect.kind());row.putLong("position",effect.position().asLong());row.put("data",effect.data());effects.add(row);}tag.put("sourceAttachments",effects);}
 @Override public void postProcess(WorldGenLevel level,StructureManager manager,ChunkGenerator generator,RandomSource random,BoundingBox clip,ChunkPos chunk,BlockPos pivot){if(!NaturalStructures.enabled()||level.getLevel().dimension()!=Level.OVERWORLD)return;dependencies.requireRegistryAndHooks();var placed=new HashSet<BlockPos>();DummyableBlock.safely(()->{for(var write:writes)if(clip.isInside(write.position())&&!level.isOutsideBuildHeight(write.position())){level.setBlock(write.position(),write.state(),write.flags());placed.add(write.position());}});for(var entry:tiles.entrySet())if(clip.isInside(entry.getKey())){var tile=level.getBlockEntity(entry.getKey());if(tile==null)throw new IllegalStateException("Missing actual planned source inventory/block entity at "+entry.getKey());tile.loadWithComponents(entry.getValue(),level.registryAccess());tile.setChanged();}for(var effect:attachments)if(clip.isInside(effect.position()))GeneratedAttachments.applyNative(effect.kind(),level,effect.position(),effect.data());for(var pos:placed){var state=level.getBlockState(pos);var updated=Block.updateFromNeighbourShapes(state,level,pos);if(updated!=state)level.setBlock(pos,updated,2);var target=level.getChunk(pos);if(target instanceof ProtoChunk&&!(target instanceof ImposterProtoChunk))target.markPosForPostprocessing(pos);}}
}
